<div class="card mb-3"><div class="card-header">Reset password</div><div class="card-body"><?= form_open('admin/peternak/reset_password/'.$pt->id,array('class'=>'d-flex gap-2')) ?><input name="password" class="form-control" placeholder="Password baru (min. 8)" minlength="8" required><button class="btn btn-outline-danger">Reset</button><?= form_close() ?></div></div>
<div class="card"><div class="card-header">Riwayat verifikasi</div><ul class="list-group list-group-flush"><?php foreach($riwayat as $r): ?><li class="list-group-item small"><?= tgl($r->created_at) ?>: <?= e($r->status_lama) ?> &rarr; <b><?= e($r->status_baru) ?></b> <?= $r->admin?'oleh '.e($r->admin):'' ?><br><?= e($r->catatan) ?></li><?php endforeach; if(!$riwayat) echo '<li class="list-group-item text-muted">Belum ada.</li>'; ?></ul></div></div></div>
